{2}   uses wincrt;

{3}   var  plithos : integer;
{4}         timi, synoliki_timi, teliki_timi, ekptosi : real;

{5}   begin
{6}      plithos := 1;
{7}      synoliki_timi := 0;
{8}      writeln('Δώσε τιμή προϊόντος : ');
{9}      readln(timi);
{10}    while  (timi = 0) do
{11}        begin
{12}            fpa:=timi * 0.18;
{13}            synoliki_timi := synoliki_timi + timi + fpa;
{14}            plithos := plithos + 1;
{15}            writeln('Δώσε τιμή προϊόντος : ');
{16}            readln(timi);
{17}        end;
{18}     if synoliki_timi > 100 then
{19}        ekptosi := synoliki_timi * 0.10
