{2}    uses wincrt;
{3}    var dorea, sum_dorea:real;
{4}    begin
{5}      sum_dorea:=1.0;
{6}      write('Δώσε ποσό είσπραξης: ');
{7}      readln(eisp);
{8}      while eisp>50 do
{9}        begin
{10}         if eisp>=0 then
{11}           begin
{12}             dorea := (trunc(eisp) - eisp);
{13}             if dorea>0 then
